export const decodeGuideVenue = (row: GuideVenueTable): StoredGuideVenue => ({
  id: row.id,
  guideId: row.guide_id,
  venueId: row.venue_id,
  status: row.status,
  orderKey: row.order_key,
  overrideText: row.override_text,
  pinned: toBool(row.pinned),
})
